{
  "name": "微孔板封膜机",
  "name_en": "Microplate Sealer",
  "manufacturer": "",
  "description": "用于实验室自动化中对微孔板进行封膜的设备，可执行封膜、开合机构控制，以及温度设置与读取。",
  "description_en": "A laboratory automation device for sealing microplates. It supports sealing, opening and closing the mechanism, and setting or reading the temperature.",
  "actions": [
    {
      "action_name": "auto-seal",
      "description": "按设定温度和持续时间执行微孔板封膜。",
      "description_en": "Seal a microplate using the specified temperature and duration."
    },
    {
      "action_name": "auto-open",
      "description": "打开封膜机机构。",
      "description_en": "Open the sealer mechanism."
    },
    {
      "action_name": "auto-close",
      "description": "关闭封膜机机构。",
      "description_en": "Close the sealer mechanism."
    },
    {
      "action_name": "auto-set_temperature",
      "description": "设置封膜机温度。",
      "description_en": "set sealer temperature"
    },
    {
      "action_name": "auto-get_temperature",
      "description": "获取封膜机温度。",
      "description_en": "get sealer temperature"
    }
  ],
  "tag_hints": [
    "microplate sealing",
    "plate sealer",
    "heat sealing",
    "temperature control",
    "lab automation"
  ]
}

